"""Fullest structures for the flower view: the most SE loop-edges closed (< 2 sigma), then the most promoter-promoter edges closed, then the widest petals relative to how tightly the anchors sit (flower score = median distance of chain midpoints between consecutive closed anchors from the SE / median anchor distance from the SE)."""
import glob, sys
from pathlib import Path
import numpy as np, pandas as pd
R0 = Path(__file__).resolve().parents[1]; O = R0 / "figure_extreme"; N = 910; L0 = 430000; files = sorted(glob.glob(sys.argv[1] + "/traj*.npz")); H = pd.read_csv(R0 / "hub_edges_all.tsv", sep="\t"); mid = lambda r: sum(map(int, r.split(":")[1].split("-"))) // 2; tb = lambda p: (p - L0) // 2000; H["b1"] = [tb(mid(x)) for x in H.reg_a]; H["b2"] = [tb(mid(x)) for x in H.reg_b]; M = pd.read_csv(R0 / "figure/conformation_metrics.tsv", sep="\t"); print(M.n_loop_closed.value_counts().sort_index().tail(4).to_dict()); se_b = tb((1248039 + 1254347) // 2); rows = []
for c in M[M.n_loop_closed >= 13].conf:
    t, k = divmod(int(c) - 1, 50); X = np.load(files[t])["X"][k, :N].astype(float); cl = np.linalg.norm(X[H.b1] - X[H.b2], axis=1) < 2; L = H[(H.from_se == 1) & (H.on_loop == 1)]; ends = sorted(int(b1 if a != "SE" else b2) for a, b1, b2, z in zip(L.a, L.b1, L.b2, np.linalg.norm(X[L.b1] - X[L.b2], axis=1) < 2) if z); ends = sorted(ends + [se_b]); d0 = np.median(np.linalg.norm(X[ends] - X[se_b], axis=1)); md = [np.linalg.norm(X[(p + q) // 2] - X[se_b]) for p, q in zip(ends[:-1], ends[1:]) if q - p > 10]; m = M[M.conf == c].iloc[0]; rows.append(dict(conf=int(c), traj=t, n_se_loop=int(m.n_loop_closed), pp=int((cl & (H.type == "promoter")).sum()), enh=int((cl & (H.type == "enhancer")).sum()), oth=int((cl & (H.type == "other")).sum()), all_closed=int(cl.sum()), flower=float(np.median(md) / d0), rg_pct=m.rg_pct, crumple_pct=m.crumple_pct, overlap=int(m.overlap)))
T = pd.DataFrame(rows).sort_values(["n_se_loop", "pp", "flower"], ascending=False); T.to_csv(O / "extreme_candidates.tsv", sep="\t", index=False); print(T.head(12).round(2).to_string(index=False)); print("from trajectories", T[T.n_se_loop == T.n_se_loop.max()].traj.nunique(), "n", (T.n_se_loop == T.n_se_loop.max()).sum())
